const now = new Date().toISOString();
const rows = [];

function sha1Short(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
}

for (const item of $input.all()) {
  const resp = item.json;
  const rawText = JSON.stringify(resp).substring(0, 100000);

  if (!resp || !resp.content || !Array.isArray(resp.content) || resp.content.length === 0) {
    rows.push({
      initiative_id:    'parse_err_' + sha1Short(now + rawText.substring(0, 100)),
      detected_at:      now,
      action_type: null, source: null, source_id: null, source_url: null,
      additional_source_ids: null, category: null, title: null, description: null,
      start_date: null, end_date: null, target_metric: null,
      related_property: null, related_channel: null,
      confidence: null, confidence_score: null,
      raw_payload:      rawText,
      parse_error_flag: true,
      inserted_at:      now
    });
    continue;
  }

  const text = resp.content.map(c => c.text || '').join('');
  let arr;
  try {
    let cleaned = text.trim();
    if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
    arr = JSON.parse(cleaned);
    if (!Array.isArray(arr)) throw new Error('not array');
  } catch (e) {
    rows.push({
      initiative_id:    'parse_err_' + sha1Short(now + text.substring(0, 100)),
      detected_at:      now,
      raw_payload:      text.substring(0, 100000),
      parse_error_flag: true,
      inserted_at:      now
    });
    continue;
  }

  for (const ent of arr) {
    if (!ent || typeof ent !== 'object') continue;
    const action = ent.action || 'create';
    if (action === 'append_source') {
      // append_source 行は raw に insert しない (KRASULA-190 で修正、KRASULA-189 の根本対応)。
      // 過去は existing_initiative_id を再利用した空メタ行を push していたが、mart 側 dedup で
      // 最新空 row が選ばれて施策消失バグの原因になっていた。downstream で append_source は
      // 使われていないため、Claude の判定結果をそのまま破棄する。
      continue;
    }
    const sourceId = ent.source_id || '';
    const newId = sha1Short((ent.source || '') + '|' + sourceId + '|' + (ent.title || '') + '|' + (ent.start_date || ''));
    rows.push({
      initiative_id:         'init_' + newId,
      detected_at:           now,
      action_type:           'create',
      source:                ent.source || null,
      source_id:             ent.source_id || null,
      source_url:            ent.source_url || null,
      additional_source_ids: null,
      category:              ent.category || null,
      title:                 ent.title || null,
      description:           ent.description || null,
      start_date:            ent.start_date || null,
      end_date:              ent.end_date || null,
      target_metric:         ent.target_metric || null,
      related_property:      ent.related_property || null,
      related_channel:       ent.related_channel || null,
      confidence:            ent.confidence || null,
      confidence_score:      typeof ent.confidence_score === 'number' ? ent.confidence_score : null,
      raw_payload:           JSON.stringify(ent).substring(0, 100000),
      parse_error_flag:      false,
      inserted_at:           now
    });
  }
}

return rows.map(json => ({ json }));
